import {esc} from './core.js';
const inline=text=>esc(text).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*]+)\*/g,'<em>$1</em>');
export function richText(text){let html='',list=false;const close=()=>{if(list){html+='</ul>';list=false}};for(const line of String(text||'').split('\n')){if(line.startsWith('- ')){if(!list){html+='<ul dir="auto">';list=true}html+=`<li>${inline(line.slice(2))}</li>`;continue}close();const heading=line.match(/^(#{1,3}) (.*)$/);if(heading){const level=heading[1].length===3?'h3':'h2';html+=`<${level} dir="auto">${inline(heading[2])}</${level}>`}else if(line.startsWith('> '))html+=`<blockquote dir="auto">${inline(line.slice(2))}</blockquote>`;else if(line)html+=`<p dir="auto">${inline(line)}</p>`;else html+='<br>'}close();return html}
